import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), x = nextInt();
        ArrayDeque<long[]> queue = new ArrayDeque<>(); // {original 1-based index, value}
        for (int i = 1; i <= n; i++) queue.add(new long[] {i, nextLong()});
        StringBuilder sb = new StringBuilder();
        for (int round = 0; round < x; round++) {
            int take = Math.min(x, queue.size());
            long[][] batch = new long[take][];
            for (int i = 0; i < take; i++) batch[i] = queue.poll();
            // First maximum wins ties (closest to the front).
            int chosen = 0;
            for (int i = 1; i < take; i++) if (batch[i][1] > batch[chosen][1]) chosen = i;
            if (round > 0) sb.append(' ');
            sb.append(batch[chosen][0]);
            for (int i = 0; i < take; i++)
                if (i != chosen) queue.add(new long[] {batch[i][0], Math.max(0, batch[i][1] - 1)});
        }
        System.out.println(sb);
    }
}
